function demoMain(idx,label){
  var specs=[["GET /users","POST /users","GET /users/{id}"],["GET /orders","POST /orders","DELETE /orders/{id}"],["GET /search?q=","POST /index","GET /health"]];
  var s=specs[idx%specs.length];
  return "["+label+"] discovered "+s.length+" endpoints: "+s.join(", ");
}

